import { useState, type HTMLAttributes } from "react";
import { Button } from "../ui/Button";
import { Select, type SelectOption } from "../ui/Select";
import { Switch } from "../ui/Switch";
import { CompositionRoot } from "./_CompositionRoot";
import type { CompositionSurfaceProps } from "./composition";

export interface SettingsCardValue {
  locale: string;
  analytics: boolean;
}

export interface SettingsCardProps extends Omit<HTMLAttributes<HTMLDivElement>, "title" | "color">, CompositionSurfaceProps {
  "data-balsa"?: string;
  title?: string;
  description?: string;
  onSave?: (value: SettingsCardValue) => void;
  onReset?: () => void;
}

const options: readonly SelectOption[] = [
  { label: "English (United States)", value: "en" },
  { label: "Português (Brasil)", value: "pt" },
];

export function SettingsCard({
  title = "Workspace settings",
  description = "Manage defaults and product behavior.",
  headingLevel,
  shadow,
  theme,
  onSave,
  onReset,
  "data-balsa": _dataBalsa,
  ...domProps
}: SettingsCardProps) {
  void _dataBalsa;
  const [locale, setLocale] = useState("en");
  const [analytics, setAnalytics] = useState(true);

  return (
    <CompositionRoot
      {...domProps}
      title={title}
      description={description}
      headingLevel={headingLevel}
      shadow={shadow}
      theme={theme}
      data-composition="settings"
      footer={
        <div className="flex justify-between gap-balsa-md">
          <Button variant="soft" onClick={onReset}>Reset</Button>
          <Button onClick={() => onSave?.({ locale, analytics })}>Save settings</Button>
        </div>
      }
    >
      <div className="grid flex-1 content-between gap-balsa-xl">
        <Select
          id="settings-locale"
          value={locale}
          label="Default language"
          options={options}
          onValueChange={(value) => {
            if (typeof value === "string") setLocale(value);
          }}
        />
        <div className="border-balsa-border pt-balsa-lg [border-top-width:var(--balsa-border-width)]">
          <Switch
            id="settings-analytics"
            checked={analytics}
            label="Usage analytics"
            hint="Share anonymous activity to improve workspace recommendations."
            onCheckedChange={setAnalytics}
          />
        </div>
      </div>
    </CompositionRoot>
  );
}

import { type HTMLAttributes, type ReactNode } from "react";
import { mergeClasses } from "../ui/classes";
import { ApplicationCard } from "./ApplicationCard";
import type { CompositionSurfaceProps } from "./composition";

export interface CompositionRootProps extends Omit<HTMLAttributes<HTMLDivElement>, "title" | "color">, CompositionSurfaceProps {
  "data-balsa"?: string;
  title: string;
  description?: string;
  action?: ReactNode;
  footer?: ReactNode;
  children?: ReactNode;
}

export function CompositionRoot({
  title,
  description,
  headingLevel = 2,
  shadow = "auto",
  theme,
  action,
  footer,
  children,
  className,
  "data-balsa": _dataBalsa,
  ...domProps
}: CompositionRootProps) {
  void _dataBalsa;

  return (
    <ApplicationCard
      {...domProps}
      title={title}
      description={description}
      headingLevel={headingLevel}
      shadow={shadow ?? "auto"}
      theme={theme}
      action={action}
      footer={footer}
      className={mergeClasses("min-w-0", className)}
    >
      {children}
    </ApplicationCard>
  );
}

import type { Shadow, ThemeInput } from "../ui/theme";

export interface CompositionSurfaceProps {
  headingLevel?: 2 | 3 | 4 | 5 | 6;
  shadow?: Shadow;
  theme?: ThemeInput;
}

export interface CompositionOption {
  label: string;
  value: string;
  description?: string;
}

export interface CompositionMetric {
  label: string;
  value: string;
  detail?: string;
}

export type CompositionPaletteColor = "primary" | "secondary" | "accent";
